layer.css:
[data-ryt="footer"] { background-color: rgb(67, 170, 96); font-style: normal; letter-spacing: normal; text-transform: none; color: var(--ryt-text) }
[data-ryt="brand"] { color: rgb(13, 110, 253); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(13, 110, 253); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"] { color: rgb(67, 170, 96); background-color: rgb(96, 0, 80); border-top: 1px solid rgba(0, 0, 0, 0); border-right: 1px solid rgba(0, 0, 0, 0); border-bottom: 1px solid rgba(0, 0, 0, 0); border-left: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(67, 170, 96); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #909294; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"]:hover { color: initial; background-color: initial }
